class DSU:
    def __init__(self, n: int):
        self.parent = list(range(n))   # every node starts as its own root
        self.rank = [0] * n            # upper bound on tree height
        self.count = n                 # number of components

    def find(self, x: int) -> int:
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])  # path compression
        return self.parent[x]

    def union(self, a: int, b: int) -> bool:
        ra, rb = self.find(a), self.find(b)
        if ra == rb:
            return False               # same set: edge (a, b) closes a cycle
        if self.rank[ra] < self.rank[rb]:
            ra, rb = rb, ra
        self.parent[rb] = ra           # shorter tree under the taller root
        if self.rank[ra] == self.rank[rb]:
            self.rank[ra] += 1
        self.count -= 1
        return True

def redundant_edge(n: int, edges: list[list[int]]) -> list[int]:
    dsu = DSU(n + 1)                   # nodes are 1..n
    for a, b in edges:
        if not dsu.union(a, b):
            return [a, b]
    return []
